select lang.id, 'TOEFL-like — Test 3', '{"duration_minutes": 45, "part_a": [{"question": "Complète : The graduate students ___ presenting their research next week.", "options": ["is", "are", "was", "has"], "correct_index": 1}, {"question": "Complète : The professor ___ have anticipated the objection.", "options": ["should", "should to", "shoulds", "shoulding"], "correct_index": 0}, {"question": "Complète : The thesis, ___ took two years to complete, was well received.", "options": ["that", "which", "who", "where"], "correct_index": 1}, {"question": "Complète : Were the funding approved, the study ___ proceed immediately.", "options": ["will", "would", "can", "shall"], "correct_index": 1}, {"question": "Complète : The paper''s conclusions ___ challenged by later research.", "options": ["was", "were", "is", "has"], "correct_index": 1}, {"question": "Complète : It is crucial that the sample ___ representative.", "options": ["is", "be", "was", "will be"], "correct_index": 1}, {"question": "Complète : The lab results, ___ reviewed twice, confirmed the hypothesis.", "options": ["having been", "having", "been", "have been"], "correct_index": 0}, {"question": "Complète : This model differs significantly ___ earlier versions.", "options": ["of", "from", "with", "to"], "correct_index": 1}, {"question": "Complète : The department requires that applicants ___ two references.", "options": ["submits", "submit", "submitted", "submitting"], "correct_index": 1}, {"question": "Complète : So compelling ___ the evidence that the jury agreed unanimously.", "options": ["was", "is", "were", "did"], "correct_index": 0}, {"question": "Complète : The article ___ peer-reviewed before publication.", "options": ["must", "must be", "must to be", "musting"], "correct_index": 1}, {"question": "Complète : The researchers, ___ findings were groundbreaking, won an award.", "options": ["who", "whose", "which", "that"], "correct_index": 1}, {"question": "Complète : The results were ___ conclusive than expected.", "options": ["less", "least", "lesser", "the less"], "correct_index": 0}, {"question": "Complète : Only after extensive testing ___ the drug approved.", "options": ["was", "did", "is", "has"], "correct_index": 0}, {"question": "Complète : The professor''s feedback helped ___ the argument.", "options": ["strengthen", "strengthening", "strengthened", "to strengthening"], "correct_index": 0}, {"question": "Complète : The survey ___ over one thousand participants.", "options": ["include", "includes", "including", "included to"], "correct_index": 1}, {"question": "Complète : ___ its limitations, the study offers valuable insights.", "options": ["Despite", "Although", "Because", "So"], "correct_index": 0}, {"question": "Complète : The findings will be presented ___ the annual conference.", "options": ["at", "in", "on", "by"], "correct_index": 0}, {"question": "Complète : What the professor emphasized ___ the importance of citations.", "options": ["was", "were", "have been", "being"], "correct_index": 0}, {"question": "Complète : The committee has yet ___ a final decision.", "options": ["making", "make", "to make", "made"], "correct_index": 2}, {"question": "Complète : The theory was later ___ by empirical evidence.", "options": ["support", "supported", "supporting", "supports"], "correct_index": 1}, {"question": "Complète : Never before ___ such a comprehensive study conducted.", "options": ["has", "have", "was", "had been"], "correct_index": 0}, {"question": "Complète : The professor''s lecture ___ several key theories.", "options": ["cover", "covers", "covering", "covered to"], "correct_index": 1}, {"question": "Complète : It was the sample''s diversity ___ strengthened the study.", "options": ["that", "who", "which is", "what"], "correct_index": 0}, {"question": "Complète : The grant application ___ before the deadline.", "options": ["must submit", "must be submitted", "must submitted", "must being submitted"], "correct_index": 1}, {"question": "Complète : The results, once published, ___ widely cited.", "options": ["become", "became", "becoming", "to become"], "correct_index": 1}, {"question": "Complète : The professor insisted that the essay ___ revised.", "options": ["is", "be", "was", "will be"], "correct_index": 1}, {"question": "Complète : The methodology section explains ___ the data was collected.", "options": ["how", "that", "which", "who"], "correct_index": 0}, {"question": "Complète : Rarely does a study generate ___ much discussion.", "options": ["so", "such", "as", "too"], "correct_index": 0}, {"question": "Complète : The dean announced that funding ___ increased next year.", "options": ["will be", "is being", "has been", "would"], "correct_index": 0}], "part_b": [{"title": "Extrait académique (géologie)", "passage": "Plate tectonics explains the movement of Earth''s lithosphere, which is divided into several large plates that float on the semi-fluid mantle beneath. The interactions between these plates, whether colliding, separating, or sliding past one another, are responsible for earthquakes, volcanic activity, and the formation of mountain ranges.", "questions": [{"question": "What does plate tectonics explain?", "options": ["Ocean currents", "The movement of Earth''s lithosphere", "Weather patterns", "Solar activity"], "correct_index": 1}, {"question": "What is the lithosphere divided into?", "options": ["Layers of water", "Several large plates", "Two continents", "Volcanic islands"], "correct_index": 1}, {"question": "What do the plates float on?", "options": ["The ocean", "The semi-fluid mantle", "Solid rock", "Ice sheets"], "correct_index": 1}, {"question": "What causes earthquakes according to the passage?", "options": ["Solar flares", "Plate interactions", "Ocean tides", "Wind patterns"], "correct_index": 1}, {"question": "What else do plate interactions cause?", "options": ["Rainfall", "Mountain range formation", "Ozone depletion", "Coral reef growth"], "correct_index": 1}, {"question": "What are the three types of plate interactions mentioned?", "options": ["Melting, freezing, evaporating", "Colliding, separating, sliding", "Rising, falling, spinning", "Heating, cooling, expanding"], "correct_index": 1}]}, {"title": "Extrait académique (littérature)", "passage": "Modernist literature, which emerged in the early twentieth century, often broke away from traditional narrative structures. Writers experimented with stream-of-consciousness techniques and fragmented timelines, reflecting the uncertainty and fragmentation of the modern world following major social and technological changes.", "questions": [{"question": "When did modernist literature emerge?", "options": ["Nineteenth century", "Early twentieth century", "Mid-twentieth century", "Twenty-first century"], "correct_index": 1}, {"question": "What did modernist writers often break away from?", "options": ["Poetry", "Traditional narrative structures", "The use of language", "Publishing houses"], "correct_index": 1}, {"question": "What technique is mentioned?", "options": ["Rhyme schemes", "Stream-of-consciousness", "Strict chronology", "Dialogue only"], "correct_index": 1}, {"question": "What did fragmented timelines reflect?", "options": ["Simplicity", "Uncertainty and fragmentation of the modern world", "Religious themes", "Rural life"], "correct_index": 1}, {"question": "What triggered these literary changes?", "options": ["Ancient traditions", "Major social and technological changes", "A single author''s influence", "Government regulation"], "correct_index": 1}, {"question": "What is the main topic of the passage?", "options": ["A biography", "Modernist literary techniques and context", "A grammar lesson", "A scientific theory"], "correct_index": 1}]}, {"title": "Extrait académique (informatique)", "passage": "Machine learning algorithms improve their performance on a task through experience, without being explicitly programmed for every scenario. By analyzing large datasets, these algorithms identify patterns and make predictions, which has led to significant advances in fields such as medical diagnosis and language translation.", "questions": [{"question": "How do machine learning algorithms improve?", "options": ["Through explicit programming only", "Through experience", "Randomly", "They don''t improve"], "correct_index": 1}, {"question": "What do these algorithms analyze?", "options": ["Small samples only", "Large datasets", "Nothing, they guess", "Only text data"], "correct_index": 1}, {"question": "What do the algorithms identify?", "options": ["Random noise", "Patterns", "Errors only", "User preferences only"], "correct_index": 1}, {"question": "What fields have benefited, according to the passage?", "options": ["Only entertainment", "Medical diagnosis and language translation", "Only sports", "Only agriculture"], "correct_index": 1}, {"question": "What do the algorithms use patterns for?", "options": ["Nothing useful", "Making predictions", "Deleting data", "Slowing down processing"], "correct_index": 1}, {"question": "What is the main topic of the passage?", "options": ["A history of computers", "How machine learning works and its applications", "A biology experiment", "A grammar rule"], "correct_index": 1}]}, {"title": "Extrait académique (philosophie)", "passage": "Utilitarianism is an ethical theory that holds that the best action is the one that maximizes overall happiness or well-being. Critics argue that this approach can justify harmful actions against a minority if they produce greater benefits for the majority, raising concerns about individual rights.", "questions": [{"question": "What does utilitarianism hold?", "options": ["Actions should follow strict rules", "The best action maximizes overall happiness", "Individual rights come first always", "Nothing matters morally"], "correct_index": 1}, {"question": "What do critics argue?", "options": ["It always protects minorities", "It can justify harm to a minority for majority benefit", "It has no flaws", "It ignores happiness entirely"], "correct_index": 1}, {"question": "What concern is raised in the passage?", "options": ["Economic growth", "Individual rights", "Climate change", "Population growth"], "correct_index": 1}, {"question": "What is the goal according to utilitarianism?", "options": ["Individual wealth", "Overall happiness or well-being", "Strict obedience to law", "Religious observance"], "correct_index": 1}, {"question": "Who might be harmed according to critics?", "options": ["The majority", "A minority", "No one", "Only leaders"], "correct_index": 1}, {"question": "What field does this passage belong to?", "options": ["Physics", "Philosophy", "Chemistry", "Geography"], "correct_index": 1}]}, {"title": "Extrait académique (climatologie)", "passage": "Ocean currents play a critical role in regulating global climate by redistributing heat from the equator toward the poles. Disruptions to these currents, potentially caused by melting ice sheets, could significantly alter weather patterns and temperatures in regions far from the source of disruption.", "questions": [{"question": "What role do ocean currents play?", "options": ["They have no effect on climate", "They regulate global climate by redistributing heat", "They only affect marine life", "They cause earthquakes"], "correct_index": 1}, {"question": "Where is heat redistributed from and to?", "options": ["Poles to equator", "Equator toward the poles", "Land to ocean only", "East to west"], "correct_index": 1}, {"question": "What could disrupt ocean currents?", "options": ["Melting ice sheets", "Increased sunlight", "Volcanic ash", "Reduced rainfall"], "correct_index": 0}, {"question": "What could disruptions cause?", "options": ["No noticeable change", "Altered weather patterns and temperatures", "Increased ocean currents everywhere", "More marine species"], "correct_index": 1}, {"question": "Are the effects limited to the source of disruption?", "options": ["Yes, only local effects", "No, effects can occur far from the source", "Not mentioned", "Effects are impossible to predict"], "correct_index": 1}, {"question": "What is the main topic of the passage?", "options": ["Ocean life", "The climate role of ocean currents", "A historical voyage", "A fishing industry report"], "correct_index": 1}]}]}'::jsonb, 'toefl'
